// src/providers/exo.ts
import { z } from "zod";
var ExoStateSchema = z.object({
  instances: z.record(z.string(), z.object({
    MlxRingInstance: z.object({
      shardAssignments: z.object({
        modelId: z.string().optional(),
        nodeToRunner: z.record(z.string(), z.string()).optional(),
        runnerToShard: z.record(z.string(), z.object({
          PipelineShardMetadata: z.object({
            modelCard: z.object({
              contextLength: z.number().optional(),
              capabilities: z.array(z.string()).optional(),
              vision: z.unknown().optional()
            }).optional()
          }).optional()
        })).optional()
      }).optional()
    }).optional()
  })).optional(),
  runners: z.record(z.string(), z.object({
    RunnerReady: z.unknown().optional()
  })).optional()
});
var ModelsResponseSchema = z.object({
  data: z.array(z.object({ owned_by: z.string().optional() })).optional()
});
async function detect(url) {
  try {
    const res = await fetch(url + "/v1/models", {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return false;
    const parsed = ModelsResponseSchema.safeParse(await res.json());
    if (!parsed.success)
      return false;
    const data = parsed.data.data;
    return data != null && data.length > 0 && data.every((item) => item.owned_by === "exo");
  } catch {
    return false;
  }
}
async function probe(url) {
  const res = await fetch(url + "/state", {
    signal: AbortSignal.timeout(1000)
  });
  if (!res.ok)
    throw new Error(`Exo probe failed: ${res.status}`);
  const body = ExoStateSchema.parse(await res.json());
  const instances = Object.values(body.instances ?? {});
  const runners = body.runners ?? {};
  return instances.flatMap((entry) => {
    const instance = entry.MlxRingInstance;
    const assignments = instance?.shardAssignments;
    const modelId = assignments?.modelId;
    if (!modelId)
      return [];
    const runnerId = Object.values(assignments.nodeToRunner ?? {})[0];
    if (!runnerId || !("RunnerReady" in (runners[runnerId] ?? {})))
      return [];
    const modelCard = assignments.runnerToShard?.[runnerId]?.PipelineShardMetadata?.modelCard;
    return [
      {
        id: modelId,
        context: modelCard?.contextLength ?? 0,
        toolcall: modelCard?.capabilities?.includes("tools") ?? false,
        vision: modelCard?.capabilities?.includes("vision") ?? modelCard?.vision != null
      }
    ];
  });
}
var exo = {
  detect,
  probe
};
var exo_default = exo;

// src/providers/llamacpp.ts
import { z as z2 } from "zod";
var PropsSchema = z2.object({
  default_generation_settings: z2.object({ n_ctx: z2.number().optional() }).optional()
});
var SlotsSchema = z2.array(z2.object({ n_ctx: z2.number().optional() }));
var ModelsResponseSchema2 = z2.object({
  data: z2.array(z2.object({
    id: z2.string(),
    meta: z2.record(z2.string(), z2.unknown()).nullable().optional()
  })).optional()
});
async function runtimeContext(url) {
  try {
    const propsRes = await fetch(url + "/props", {
      signal: AbortSignal.timeout(1000)
    });
    if (propsRes.ok) {
      const parsed = PropsSchema.parse(await propsRes.json());
      if (parsed.default_generation_settings?.n_ctx) {
        return parsed.default_generation_settings.n_ctx;
      }
    }
  } catch {}
  try {
    const slotsRes = await fetch(url + "/slots", {
      signal: AbortSignal.timeout(1000)
    });
    if (slotsRes.ok) {
      const parsed = SlotsSchema.parse(await slotsRes.json());
      const loaded = parsed.find((slot) => slot.n_ctx && slot.n_ctx > 0)?.n_ctx;
      if (loaded)
        return loaded;
    }
  } catch {}
  return null;
}
async function detect2(url) {
  try {
    const res = await fetch(url, {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return false;
    return res.headers.get("Server")?.toLowerCase() === "llama.cpp";
  } catch {
    return false;
  }
}
async function probe2(url) {
  const loadedContext = await runtimeContext(url);
  const res = await fetch(url + "/v1/models", {
    signal: AbortSignal.timeout(1000)
  });
  if (!res.ok)
    throw new Error(`llama.cpp probe failed: ${res.status}`);
  const body = ModelsResponseSchema2.parse(await res.json());
  return (body.data ?? []).map((item) => ({
    id: item.id,
    context: Number(loadedContext ?? item.meta?.n_ctx ?? item.meta?.n_ctx_train ?? 0),
    toolcall: false,
    vision: false
  }));
}
var llamacpp = {
  detect: detect2,
  probe: probe2
};
var llamacpp_default = llamacpp;

// src/providers/llamaswap.ts
import { z as z3 } from "zod";
var ModelsResponseSchema3 = z3.object({
  data: z3.array(z3.object({
    id: z3.string(),
    owned_by: z3.string().optional()
  })).optional()
});
var RunningResponseSchema = z3.object({
  running: z3.array(z3.object({
    model: z3.string(),
    state: z3.string().optional()
  })).optional()
});
async function runningModels(url) {
  try {
    const res = await fetch(url + "/running", {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return new Set;
    const body = RunningResponseSchema.parse(await res.json());
    return new Set((body.running ?? []).filter((item) => !item.state || item.state === "ready").map((item) => item.model));
  } catch {
    return new Set;
  }
}
async function detect3(url) {
  try {
    const res = await fetch(url + "/v1/models", {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return false;
    const parsed = ModelsResponseSchema3.safeParse(await res.json());
    if (!parsed.success)
      return false;
    const data = parsed.data.data;
    if (!data)
      return false;
    return data.some((item) => item.owned_by === "llama-swap");
  } catch {
    return false;
  }
}
async function probe3(url) {
  const res = await fetch(url + "/v1/models", {
    signal: AbortSignal.timeout(1000)
  });
  if (!res.ok)
    throw new Error(`llama-swap probe failed: ${res.status}`);
  const body = ModelsResponseSchema3.parse(await res.json());
  if (!body.data)
    throw new Error("llama-swap probe failed: no data field");
  const loadedModels = await runningModels(url);
  return Promise.all(body.data.filter((item) => loadedModels.has(item.id)).map(async (item) => {
    const context = await runtimeContext(`${url}/upstream/${item.id}`) ?? 0;
    return {
      id: item.id,
      context,
      toolcall: false,
      vision: false
    };
  }));
}
var llamaswap = {
  detect: detect3,
  probe: probe3
};
var llamaswap_default = llamaswap;

// src/providers/lmstudio.ts
import { z as z4 } from "zod";
var GreetingResponseSchema = z4.object({
  lmstudio: z4.boolean().optional()
});
var ModelItemSchema = z4.object({
  id: z4.string(),
  type: z4.enum(["llm", "vlm", "embeddings"]),
  state: z4.enum(["loaded", "loading", "not-loaded"]),
  loaded_context_length: z4.number().optional(),
  capabilities: z4.array(z4.string()).optional()
});
var ModelsResponseSchema4 = z4.object({
  data: z4.array(ModelItemSchema).optional()
});
async function detect4(url) {
  try {
    const res = await fetch(url + "/lmstudio-greeting", {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return false;
    const parsed = GreetingResponseSchema.safeParse(await res.json());
    if (!parsed.success)
      return false;
    return parsed.data.lmstudio === true;
  } catch {
    return false;
  }
}
async function probe4(url) {
  const res = await fetch(url + "/api/v0/models", {
    signal: AbortSignal.timeout(1000)
  });
  if (!res.ok)
    throw new Error(`LM Studio probe failed: ${res.status}`);
  const body = ModelsResponseSchema4.parse(await res.json());
  if (!body.data)
    throw new Error("LM Studio probe failed: no data field");
  return body.data.filter((item) => item.state === "loaded").filter((item) => item.type === "llm" || item.type === "vlm").map((item) => ({
    id: item.id,
    context: item.loaded_context_length ?? 0,
    toolcall: item.capabilities?.includes("tool_use") ?? false,
    vision: item.type === "vlm"
  }));
}
var lmstudio = {
  detect: detect4,
  probe: probe4
