var lmstudio_default = lmstudio;

// src/providers/mlxvlm.ts
import { z as z5 } from "zod";
var HealthSchema = z5.object({
  status: z5.string().optional(),
  loaded_model: z5.string().nullable().optional(),
  loaded_context_size: z5.number().nullable().optional(),
  loaded_tool_parser: z5.string().nullable().optional()
});
async function runtimeHealth(url, timeout = 1000) {
  const res = await fetch(url + "/health", {
    signal: AbortSignal.timeout(timeout)
  });
  if (!res.ok) {
    return null;
  }
  return HealthSchema.parse(await res.json());
}
async function detect5(url) {
  try {
    const res = await fetch(url + "/health", {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok) {
      return false;
    }
    return res.headers.get("Server")?.toLowerCase().includes("mlx_vlm") ?? false;
  } catch {
    return false;
  }
}
async function probe5(url) {
  const health = await runtimeHealth(url);
  if (!health) {
    throw new Error("MLX-VLM probe failed: health endpoint unavailable");
  }
  const loadedModel = health.loaded_model ?? undefined;
  if (!loadedModel) {
    return [];
  }
  return [
    {
      id: loadedModel,
      context: health.loaded_context_size ?? 0,
      toolcall: health.loaded_tool_parser !== undefined && health.loaded_tool_parser !== null,
      vision: true
    }
  ];
}
var mlxvlm = {
  detect: detect5,
  probe: probe5
};
var mlxvlm_default = mlxvlm;

// src/providers/ollama.ts
import { z as z6 } from "zod";
var ModelsResponseSchema5 = z6.object({
  models: z6.array(z6.object({
    name: z6.string(),
    model: z6.string(),
    context_length: z6.number()
  })).optional()
});
var ShowResponseSchema = z6.object({
  capabilities: z6.array(z6.string()).optional()
});
async function detect6(url) {
  try {
    const res = await fetch(url, {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return false;
    return await res.text() === "Ollama is running";
  } catch {
    return false;
  }
}
async function show(url, model) {
  try {
    const res = await fetch(url + "/api/show", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ model }),
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return {};
    return ShowResponseSchema.parse(await res.json());
  } catch {
    return {};
  }
}
async function probe6(url) {
  const res = await fetch(url + "/api/ps", {
    signal: AbortSignal.timeout(1000)
  });
  if (!res.ok)
    throw new Error(`Ollama probe failed: ${res.status}`);
  const body = ModelsResponseSchema5.parse(await res.json());
  if (!body.models)
    throw new Error("Ollama probe failed: no models field");
  return Promise.all(body.models.map(async (item) => {
    const extra = await show(url, item.model);
    return {
      id: item.name,
      context: item.context_length,
      toolcall: extra.capabilities?.includes("tools") ?? false,
      vision: extra.capabilities?.includes("vision") ?? false
    };
  }));
}
var ollama = {
  detect: detect6,
  probe: probe6
};
var ollama_default = ollama;

// src/providers/omlx.ts
import { z as z7 } from "zod";
var HealthSchema2 = z7.object({
  status: z7.string().optional(),
  engine_pool: z7.object({
    model_count: z7.number().optional()
  }).optional()
});
var StatusResponseSchema = z7.object({
  models: z7.array(z7.object({
    id: z7.string(),
    loaded: z7.boolean().optional(),
    model_type: z7.string().optional(),
    engine_type: z7.string().optional(),
    max_context_window: z7.number().optional()
  }))
});
async function detect7(url) {
  try {
    const res = await fetch(url + "/health", {
      signal: AbortSignal.timeout(1000)
    });
    if (!res.ok)
      return false;
    const parsed = HealthSchema2.safeParse(await res.json());
    return parsed.success && parsed.data.engine_pool !== undefined;
  } catch {
    return false;
  }
}
async function probe7(url) {
  const res = await fetch(url + "/v1/models/status", {
    signal: AbortSignal.timeout(1000)
  });
  if (!res.ok)
    throw new Error(`oMLX probe failed: ${res.status}`);
  const body = StatusResponseSchema.parse(await res.json());
  return body.models.filter((m) => {
    if (m.loaded !== true)
      return false;
    const t = m.model_type ?? "";
    return t === "llm" || t === "vlm";
  }).map((m) => {
    const modelType = m.model_type ?? "";
    return {
      id: m.id,
      context: m.max_context_window ?? 0,
      toolcall: true,
      vision: modelType === "vlm"
    };
  });
