var omlx = {
  detect: detect7,
  probe: probe7
};
var omlx_default = omlx;

// src/providers/vllm.ts
import { z as z8 } from "zod";
var ModelsResponseSchema6 = z8.object({
  data: z8.array(z8.object({
    id: z8.string(),
    owned_by: z8.string().optional(),
