var supportedProviderKinds = Object.keys(supportedProviders);

// src/types.ts
var KINDS = ["ollama", "lmstudio", "llamacpp", "vllm", "exo", "llamaswap", "omlx", "mlxvlm"];

// src/url.ts
function trimURL(url) {
  return url.trim().replace(/\/+$/, "");
}
function baseURL(url) {
  const next = trimURL(url);
  if (!next)
    return "";
  return next.endsWith("/v1") ? next : `${next}/v1`;
}
function rootURL(url) {
  const next = trimURL(url);
  if (!next)
    return "";
  return next.endsWith("/v1") ? next.slice(0, -3) : next;
}

// src/config.ts
function getV1OpencodeClientConfig(input) {
  return input._client?.getConfig?.() ?? {};
}
function createV2OpencodeClient(url, input) {
  const v1ClientConfig = getV1OpencodeClientConfig(input);
  return createOpencodeClient({
    baseUrl: url.toString(),
    fetch: v1ClientConfig.fetch,
    headers: v1ClientConfig.headers,
    throwOnError: true
  });
}
function parseTargetConfig(item) {
  if (typeof item === "string" && item)
    return { url: baseURL(item) };
  if (item && typeof item === "object") {
    const url = "url" in item ? item.url : undefined;
    const kind = "kind" in item ? item.kind : undefined;
    if (typeof url === "string" && url) {
      return {
        url: baseURL(url),
        ...typeof kind === "string" && KINDS.includes(kind) ? { kind } : {}
      };
    }
  }
}
var defaults = Object.fromEntries(Object.entries(supportedProviderDefaultURLs).map(([id, url]) => [
  id,
  {
    url: baseURL(url),
    kind: id
  }
]));
function getConfiguredTargets(provider) {
  const raw = provider?.options?.targets;
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    const next = Object.fromEntries(Object.entries(raw).map(([id, item]) => {
      const val = parseTargetConfig(item);
      if (!val)
        return;
      return [id, val];
    }).filter((item) => Boolean(item)));
    if (Object.keys(next).length)
      return next;
  }
  const url = provider?.options?.baseURL;
  if (typeof url === "string" && url) {
    return {
      [LEGACY_TARGET_ID]: {
        url: baseURL(url)
      }
    };
  }
  return {};
}
function getProviderTargets(provider) {
  const configured = getConfiguredTargets(provider);
  if (provider?.options?.includeDefaults === false)
    return configured;
  const urls = new Set(Object.values(configured).map((item) => item.url));
  const builtin = Object.fromEntries(Object.entries(defaults).filter(([id, item]) => !configured[id] && !urls.has(item.url)));
  return {
    ...builtin,
    ...configured
  };
}
async function getCurrentProviderConfig(url, input) {
  const cfg = await createV2OpencodeClient(url, input).global.config.get();
  const provider = cfg.data?.provider?.[LOCAL_PROVIDER_ID];
  return {
    targets: getConfiguredTargets(provider),
    key: typeof provider?.options?.apiKey === "string" ? provider.options.apiKey : ""
  };
}
async function saveProviderTarget(server, input, id, url, kind, key) {
  const cur = await getCurrentProviderConfig(server, input);
  const options = {
    targets: {
      ...cur.targets,
      [id]: {
        url: baseURL(url),
        ...kind ? { kind } : {}
      }
    }
  };
  if (key !== undefined)
    options.apiKey = key;
  await createV2OpencodeClient(server, input).global.config.update({
    config: {
      provider: {
        [LOCAL_PROVIDER_ID]: {
          options
        }
      }
    }
  });
}

// src/models.ts
function limits(input) {
  const context = input > 0 ? input : DEFAULT_CONTEXT;
  return {
    context,
    output: Math.min(context, DEFAULT_OUTPUT)
  };
}
function id(target, model) {
  return `${target}/${model}`;
}
function name(target, model) {
